class TransactionManager {
  async execute<T>(
    operations: Array<() => Promise<any>>,
    onRollback?: () => Promise<void>
  ): Promise<T[]> {
    const results = [];
    try {
      for (const op of operations) {
        results.push(await op());
      }
      return results;
    } catch (error) {
      if (onRollback) await onRollback();
      throw error;
    }
  }
}

